# --- FILE: https://raw.githubusercontent.com/tidyverse/dplyr/main/data-raw/starwars.R ---
library(tidyverse)
library(httr)

get_all <- function(url) {
  out <- NULL

  while (!is.null(url)) {
    message("Getting ", url)
    req <- GET(url)
    stop_for_status(req)

    con <- content(req)
    out <- c(out, con$results)
    url <- con$`next`
  }

  out
}

people <- get_all("https://swapi.py4e.com/api/people/?format=json")
str(people[[1]])

# Generate lookup tables --------------------------------------------------

lookup <- function(url, name = "name") {
  all <- get_all(url)

  url <- all |> map_chr("url")
  name <- all |> map_chr(name)
  name[name == "unknown"] <- NA

  set_names(name, url)
}

species <- lookup("https://swapi.py4e.com/api/species/?format=json")
films <- lookup("https://swapi.py4e.com/api/films/?format=json", "title")
planets <- lookup("https://swapi.py4e.com/api/planets/?format=json")
vehicles <- lookup("https://swapi.py4e.com/api/vehicles/?format=json")
starships <- lookup("https://swapi.py4e.com/api/starships/?format=json")

starwars <- tibble(
  name = people |> map_chr("name"),
  height = people |>
    map_chr("height") |>
    parse_integer(na = c("unknown", "none")),
  mass = people |> map_chr("mass") |> parse_number(na = "unknown"),
  hair_color = people |> map_chr("hair_color") |> parse_character(na = "n/a"),
  skin_color = people |> map_chr("skin_color"),
  eye_color = people |> map_chr("eye_color"),
  birth_year = people |>
    map_chr("birth_year") |>
    parse_number(na = "unknown"),
  sex = people |> map_chr("gender") |> parse_character(na = "n/a"),
  gender = NA_character_,
  homeworld = people |> map_chr("homeworld") |> planets[.] |> unname(),
  species = people |>
    map("species") |>
    map_chr(1, .null = NA) |>
    species[.] |>
    unname(),
  films = people |>
    map("films") |>
    map(. |> flatten_chr() |> films[.] |> unname()),
  vehicles = people |>
    map("vehicles", .default = list()) |>
    map(. |> flatten_chr() |> vehicles[.] |> unname()),
  starships = people |>
    map("starships", .default = list()) |>
    map(. |> flatten_chr() |> starships[.] |> unname())
)

# Add gender --------------------------------------------------------------

# For asexual and hermaphroditic individuals we need to add some manually
# collected data from @MeganBeckett.

# Droids are robots and do not have a biological sex. But they
# they have a gender, determined by how they were programmed:
# https://starwars.fandom.com/wiki/Sexes
#
# Hutts are hermaphroditic, but identify as either male or female

genders <- c(
  "C-3PO" = "masculine", # https://starwars.fandom.com/wiki/C-3PO
  "BB8" = "masculine", # https://starwars.fandom.com/wiki/BB-8
  "IG-88" = "masculine", # https://starwars.fandom.com/wiki/IG-88
  "R5-D4" = "masculine", # https://starwars.fandom.com/wiki/R5-D4
  "R2-D2" = "masculine", # https://starwars.fandom.com/wiki/R2-D2
  "R4-P17" = "feminine", # https://starwars.fandom.com/wiki/R4-P17
  "Jabba Desilijic Tiure" = "masculine" # https://starwars.fandom.com/wiki/Jabba_Desilijic_Tiure
)

starwars <- mutate(
  starwars,
  sex = ifelse(sex == "hermaphrodite", "hermaphroditic", sex),
  species = ifelse(name == "R4-P17", "Droid", species), # R4-P17 is a droid
  sex = ifelse(species == "Droid", "none", sex), # Droids don't have biological sex
  gender = case_when(
    sex == "male" ~ "masculine",
    sex == "female" ~ "feminine",
    .default = unname(genders[name])
  )
)

starwars |> filter(is.na(sex)) |> select(name, species, gender, sex)

starwars |> count(gender, sort = TRUE)
starwars |> count(sex, gender, sort = TRUE)

# Fix a typo --------------------------------------------------------------

# see https://github.com/tidyverse/dplyr/pull/6840
starwars = starwars |>
  mutate(
    name = ifelse(name == "Beru Whitesun lars", "Beru Whitesun Lars", name)
  )

# Basic checks -------------------------------------------------------------

starwars |> count(species, sort = TRUE)
starwars |> count(homeworld, sort = TRUE)
starwars |> count(skin_color, sort = TRUE)

starwars |> group_by(species) |> summarise(mass = mean(mass, na.rm = T))

# Save --------------------------------------------------------------------

# Save in convenient form for diffs
starwars |>
  mutate_if(is.list, ~ map_chr(., paste, collapse = ", ")) |>
  write_csv("data-raw/starwars.csv")

usethis::use_data(starwars, overwrite = TRUE)


# --- FILE: https://raw.githubusercontent.com/tidyverse/dplyr/main/data-raw/storms.R ---
library(tidyverse)

# Creates storms data set from NOAA Atlantic Hurricane data, which is provided
# in an unorthodox format: a csv that alternates between metadata/identifier rows
# and data rows.

# TO UPDATE: get the latest URL from https://www.nhc.noaa.gov/data/#hurdat, and rerun this code

# Read in data set so each line is a character string
storm_file_complete <- read_file(
  "https://www.nhc.noaa.gov/data/hurdat/hurdat2-1851-2024-040425.txt"
)
storm_strings <- read_lines(storm_file_complete)

# Identify the header lines that have three commas
header_locations <- str_count(storm_strings, "\\,") == 3
header_locations <- (1:length(storm_strings))[header_locations]

# Extract length of each sub-dataset
headers <- as.list(storm_strings[header_locations])
headers_df <- headers |>
  map(str_sub, start = 1, end = -2) |> # to remove trailing comma
  map(paste0, "\n") |> # to trigger literal read
  map_df(read_csv, col_names = c("id", "name", "n_obs"), col_types = "cci") |>
  mutate(name = recode(name, "UNNAMED" = id), skip = header_locations) |>
  select(id, name, skip, n_obs)

column_types <- list(
  date = col_character(),
  time = col_character(),
  record_type = col_character(),
  status = col_character(),
  lat = col_character(),
  long = col_character(),
  wind = col_integer(),
  pressure = col_integer(),
  extent_34_NE = col_integer(),
  extent_34_SE = col_integer(),
  extent_34_SW = col_integer(),
  extent_34_NW = col_integer(),
  extent_50_NE = col_integer(),
  extent_50_SE = col_integer(),
  extent_50_SW = col_integer(),
  extent_50_NW = col_integer(),
  extent_64_NE = col_integer(),
  extent_64_SE = col_integer(),
  extent_64_SW = col_integer(),
  extent_64_NW = col_integer(),
  nas = col_integer()
)
column_names <- names(column_types)

#### Parse each storm as its own sub-dataframe
storm_dataframes <- vector("list", nrow(headers_df))
for (i in 1:nrow(headers_df)) {
  # get this storm's metadata
  row_start = headers_df[i, ]$skip + 1
  row_end = headers_df[i, ]$n_obs + row_start - 1
  # subset of rows belonging to this storm
  data_subset = storm_strings[row_start:row_end] |>
    paste(collapse = "\n") |>
    paste0("\n")
  # read it as a csv
  data_subset = read_csv(
    data_subset,
    col_names = column_names,
    col_types = column_types,
    na = c("", "-99", "-999")
  )
  problems()
  # name and id at the front
  data_subset$name = headers_df[i, ]$name
  data_subset = data_subset |> relocate(name)
  data_subset$id = headers_df[i, ]$id
  data_subset = data_subset |> relocate(id)
  # add to list of storms
  storm_dataframes[[i]] = data_subset
}

# Combine and clean the data sets
library(lubridate)

# combine the storms into one dataframe
storms <- storm_dataframes |>
  bind_rows()

#####################
# format and cleanup

# format the columns
storms <- storms |>
  mutate(
    date = ymd(date),
    year = year(date),
    month = month(date),
    day = day(date),
    hour = as.numeric(str_sub(time, 1, 2)),
    lat_hemisphere = str_sub(lat, -1),
    lat_sign = if_else(lat_hemisphere == "N", 1, -1),
    lat = as.numeric(str_sub(lat, 1, -2)) * lat_sign,
    long_hemisphere = str_sub(long, -1),
    long_sign = if_else(long_hemisphere == "E", 1, -1),
    long = as.numeric(str_sub(long, 1, -2)) * long_sign,
    # wind = wind * 1.15078, # transforms knots to mph,
    TSradius1 = extent_34_NE + extent_34_SW,
    TSradius2 = extent_34_NW + extent_34_SE,
    tropicalstorm_force_diameter = pmax(TSradius1, TSradius2),
    HUradius1 = extent_64_NE + extent_64_SW,
    HUradius2 = extent_64_NW + extent_64_SE,
    hurricane_force_diameter = pmax(HUradius1, HUradius2)
  )

# drop rows with missing pressure record
storms <- storms |>
  filter(!is.na(pressure))

# don't abrev.
storms <- storms |>
  mutate(
    status = factor(recode(
      status,
      "HU" = "hurricane",
      "TS" = "tropical storm",
      "TD" = "tropical depression",
      "EX" = "extratropical",
      "SD" = "subtropical depression",
      "SS" = "subtropical storm",
      "LO" = "other low",
      "WV" = "tropical wave",
      "DB" = "disturbance"
    ))
  )

# hurricane category
storms <- storms |>
  mutate(
    category = case_when(
      status != "hurricane" ~ NA,
      wind >= 137 ~ 5,
      wind >= 113 ~ 4,
      wind >= 96 ~ 3,
      wind >= 83 ~ 2,
      wind >= 64 ~ 1,
      .default = NA
    )
  ) |>
  relocate(category, .after = status)

# drop storms without at least one record that is a tropical depression or higher
storms <- storms |>
  group_by(year, name) |>
  filter(any(
    status %in% c("hurricane", "tropical storm", "tropical depression")
  )) |>
  ungroup()

# drop all rows that are not at least a depression
# might want to use this filter if the file size is an issue
# storms <- storms |> filter(status %in% c("hurricane", "tropical storm", "tropical depression"))

# make names Title casing
storms <- storms |>
  mutate(
    name = if_else(
      str_sub(name, 1, 3) %in% c("AL0", "AL1"),
      name,
      str_to_title(name)
    )
  )

# drop a bad data point (add more if found)
storms <- storms |>
  filter(!((year == 1969) & (name == "Debbie") & (long < -350)))

# simplify
storms <- storms |>
  # drop historical data for simplicity and backwards compatibility
  filter(year >= 1975) |>
  # drop some columns
  select(
    name,
    year,
    month,
    day,
    hour,
    lat,
    long,
    status,
    category,
    wind,
    pressure,
    tropicalstorm_force_diameter,
    hurricane_force_diameter
  )

# save in convenient form for diffs
storms |>
  write_csv("data-raw/storms.csv")

# output for the package
usethis::use_data(storms, overwrite = TRUE)


