test_that("rlang lambda inherit from the data mask (#3843)", {
  res <- iris |>
    mutate_at(
      vars(starts_with("Petal")),
      ~ ifelse(Species == "setosa" & . < 1.5, NA, .)
    )
  expected <- iris |>
    mutate(
      Petal.Length = ifelse(
        Species == "setosa" & Petal.Length < 1.5,
        NA,
        Petal.Length
      ),
      Petal.Width = ifelse(
        Species == "setosa" & Petal.Width < 1.5,
        NA,
        Petal.Width
      )
    )
  expect_identical(res, expected)

  res <- iris |>
    group_by(Species) |>
    mutate_at(
      vars(starts_with("Petal")),
      ~ ifelse(Species == "setosa" & . < 1.5, NA, .)
    )
  expected <- iris |>
    group_by(Species) |>
    mutate(
      Petal.Length = ifelse(
        Species == "setosa" & Petal.Length < 1.5,
        NA,
        Petal.Length
      ),
      Petal.Width = ifelse(
        Species == "setosa" & Petal.Width < 1.5,
        NA,
        Petal.Width
      )
    )
  expect_identical(res, expected)
})

