test_that("do() gives meaningful error messages", {
  df <- data.frame(
    g = c(1, 2, 2, 3, 3, 3),
    x = 1:6,
    y = 6:1
  ) |>
    group_by(g)

  expect_snapshot({
    (expect_error(df |> do(head, tail)))

    # unnamed elements must return data frames
    (expect_error(df |> ungroup() |> do(1)))
    (expect_error(df |> do(1)))
