  expect_equal(test$Date[1:4], test2$Date)
  test2 <- test |> filter_out(Date < ISOdate(2010, 01, 01, 5))
  expect_equal(test$Date[5:10], test2$Date)
})

test_that("filter and filter_out discards NA", {
