test_that("filter() and filter_out() preserve order across groups (#3989)", {
  df <- tibble(
    g = c(1, 2, 1, 2, 1),
    time = 5:1,
    x = 5:1
  )

  res1 <- df |>
    group_by(g) |>
    filter(x <= 4) |>
    arrange(time)

  res2 <- df |>
    group_by(g) |>
    arrange(time) |>
    filter(x <= 4)

  res3 <- df |>
    filter(x <= 4) |>
    arrange(time) |>
    group_by(g)

  expect_identical(res1$time, 1:4)
  expect_equal(res1, res2)
  expect_equal(res1, res3)

  res1 <- df |>
    group_by(g) |>
    filter_out(x <= 2) |>
    arrange(time)

  res2 <- df |>
    group_by(g) |>
    arrange(time) |>
    filter_out(x <= 2)

  res3 <- df |>
    filter_out(x <= 2) |>
    arrange(time) |>
    group_by(g)

  expect_identical(res1$time, 3:5)
  expect_equal(res1, res2)
  expect_equal(res1, res3)
})

test_that("filter() with two conditions does not freeze (#4049)", {
