test_that("filter() gives useful error messages", {
  expect_snapshot({
    # wrong type
    (expect_error(
      iris |>
        group_by(Species) |>
        filter(1:n())
    ))
    (expect_error(
      iris |>
        filter(1:n())
    ))

    # matrix with > 1 columns
    (expect_error(
      filter(
        data.frame(x = 1:2),
        matrix(c(TRUE, FALSE, TRUE, FALSE), nrow = 2)
      )
    ))

    # wrong size
    (expect_error(
      iris |>
        group_by(Species) |>
        filter(c(TRUE, FALSE))
    ))
    (expect_error(
      iris |>
        rowwise(Species) |>
        filter(c(TRUE, FALSE))
    ))
    (expect_error(
      iris |>
        filter(c(TRUE, FALSE))
    ))

    # evaluation error
    (expect_error(
      mtcars |> filter(`_x`)
    ))
    (expect_error(
      mtcars |>
        group_by(cyl) |>
        filter(`_x`)
    ))

    # named inputs
    (expect_error(
      filter(mtcars, x = 1)
    ))
    (expect_error(
      filter(mtcars, y > 2, z = 3)
    ))
    (expect_error(
      filter(mtcars, TRUE, x = 1)
    ))

    # ts
    (expect_error(
      filter(ts(1:10))
    ))

    # Error that contains {
    (expect_error(
      tibble() |> filter(stop("{"))
    ))
  })
})

test_that("Using data frames in `filter()` is defunct (#7758)", {
  df <- data.frame(x = 1, y = 1)
  gdf <- group_by(df, x)
  rdf <- rowwise(df, x)

  # Use `if_any()` or `if_all()`, not `across()`
  expect_snapshot(error = TRUE, {
    filter(df, across(everything(), ~ .x > 0))
  })
  expect_snapshot(error = TRUE, {
    filter(gdf, across(everything(), ~ .x > 0))
  })
  expect_snapshot(error = TRUE, {
    filter(rdf, across(everything(), ~ .x > 0))
  })

  # Can't filter with a data frame of logicals (same as the `across()` case)
  expect_snapshot(error = TRUE, {
    filter(df, tibble(x > 0, y > 0))
  })
  expect_snapshot(error = TRUE, {
    filter(gdf, tibble(x > 0, y > 0))
  })
  expect_snapshot(error = TRUE, {
    filter(rdf, tibble(x > 0, y > 0))
  })
})

test_that("filter and filter_out preserve grouping", {
  gf <- group_by(tibble(g = c(1, 1, 1, 2, 2), x = 1:5), g)

  i <- count_regroups(out <- filter(gf, x %in% c(3, 4)))
  expect_equal(i, 0L)
  expect_equal(group_vars(gf), "g")
  expect_equal(group_rows(out), list_of(1L, 2L))

  i <- count_regroups(out <- filter_out(gf, x %in% c(3, 4)))
  expect_equal(i, 0L)
  expect_equal(group_vars(gf), "g")
  expect_equal(group_rows(out), list_of(1:2, 3L))

  i <- count_regroups(out <- filter(gf, x < 3))
  expect_equal(i, 0L)
  expect_equal(group_vars(gf), "g")
  expect_equal(group_rows(out), list_of(c(1L, 2L)))

  i <- count_regroups(out <- filter_out(gf, x < 3))
  expect_equal(i, 0L)
  expect_equal(group_vars(gf), "g")
  expect_equal(group_rows(out), list_of(1L, 2:3))
})

test_that("filter() and filter_out() with empty dots still calls dplyr_row_slice()", {
  tbl <- new_tibble(list(x = 1), nrow = 1L)
  foo <- structure(tbl, class = c("foo_df", class(tbl)))

  local_methods(
    # `foo_df` always loses class when row slicing
    dplyr_row_slice.foo_df = function(data, i, ...) {
      out <- NextMethod()
      new_tibble(out, nrow = nrow(out))
    }
  )

  expect_s3_class(filter(foo), class(tbl), exact = TRUE)
  expect_s3_class(filter_out(foo), class(tbl), exact = TRUE)

  expect_s3_class(filter(foo, x == 1), class(tbl), exact = TRUE)
  expect_s3_class(filter_out(foo, x == 1), class(tbl), exact = TRUE)
})

test_that("can filter() with unruly class", {
  local_methods(
    `[.dplyr_foobar` = function(x, i, ...) new_dispatched_quux(vec_slice(x, i)),
    dplyr_row_slice.dplyr_foobar = function(x, i, ...) x[i, ]
  )

  df <- foobar(data.frame(x = 1:3))
  expect_identical(
    filter(df, x <= 2),
    quux(data.frame(x = 1:2, dispatched = TRUE))
  )
})

test_that("filter() preserves the call stack on error (#5308)", {
  foobar <- function() stop("foo")

  stack <- NULL
  expect_error(
    withCallingHandlers(
      error = function(...) stack <<- sys.calls(),
      filter(mtcars, foobar())
    )
  )

  expect_true(some(stack, is_call, "foobar"))
})

test_that("if_any() and if_all() work", {
  df <- tibble(x1 = 1:10, x2 = c(1:5, 10:6))

  expect_equal(
    filter(df, if_all(starts_with("x"), ~ . > 6)),
    filter(df, x1 > 6 & x2 > 6)
  )
  expect_equal(
    filter_out(df, if_all(starts_with("x"), ~ . > 6)),
    filter_out(df, x1 > 6 & x2 > 6)
  )

  expect_equal(
    filter(df, if_any(starts_with("x"), ~ . > 6)),
    filter(df, x1 > 6 | x2 > 6)
  )
  expect_equal(
    filter_out(df, if_any(starts_with("x"), ~ . > 6)),
    filter_out(df, x1 > 6 | x2 > 6)
  )
})

