  )
})

test_that("`dplyr_reconstruct()` doesn't modify the original `data` in place", {
  data <- new_data_frame(list(x = 1), foo = "bar")
  template <- vctrs::data_frame(x = 1)

  out <- dplyr_reconstruct(data, template)

  expect_null(attr(out, "foo"))
  expect_identical(attr(data, "foo"), "bar")
})

test_that("`dplyr_reconstruct()`, which gets and sets attributes, doesn't touch `row.names` (#6525)", {
  skip_if_no_lazy_character()

  dplyr_attributes <- function(x) {
    .Call(ffi_test_dplyr_attributes, x)
  }
  dplyr_set_attributes <- function(x, attributes) {
    .Call(ffi_test_dplyr_set_attributes, x, attributes)
  }

  df <- vctrs::data_frame(x = 1)

  attributes <- attributes(df)
  attributes$row.names <- new_lazy_character(function() "a")
  attributes <- as.pairlist(attributes)

  df_with_lazy_row_names <- dplyr_set_attributes(df, attributes)

  # Ensure `data` row names aren't materialized
  x <- dplyr_reconstruct(df_with_lazy_row_names, df)
  attributes <- dplyr_attributes(df_with_lazy_row_names)
  expect_false(lazy_character_is_materialized(attributes$row.names))

  # `data` row names should also propagate into the result unmaterialized
  attributes <- dplyr_attributes(x)
  expect_false(lazy_character_is_materialized(attributes$row.names))

  # Ensure `template` row names aren't materialized
  x <- dplyr_reconstruct(df, df_with_lazy_row_names)
  attributes <- dplyr_attributes(df_with_lazy_row_names)
  expect_false(lazy_character_is_materialized(attributes$row.names))
})


# --- FILE: https://raw.githubusercontent.com/tidyverse/dplyr/main/tests/testthat/test-group-by.R ---
df <- data.frame(x = rep(1:3, each = 10), y = rep(1:6, each = 5))

test_that("group_by() with .add = TRUE adds groups", {
  add_groups1 <- function(tbl) group_by(tbl, x, y, .add = TRUE)
  add_groups2 <- function(tbl) {
    group_by(group_by(tbl, x, .add = TRUE), y, .add = TRUE)
  }

  expect_equal(group_vars(add_groups1(df)), c("x", "y"))
  expect_equal(group_vars(add_groups2(df)), c("x", "y"))
})

test_that("group_by(<grouped df>, <computation>) computes the expressions on the ungrouped data frame (#5938)", {
  df <- data.frame(
    x = 1:4,
    g = rep(1:2, each = 2)
  )

  count <- 0
  out <- df |>
    group_by(g) |>
    group_by(big = {
      count <<- count + 1
      x > mean(x)
    })
  expect_equal(out$big, c(FALSE, FALSE, TRUE, TRUE))
  expect_equal(count, 1L)
  expect_equal(group_vars(out), c("big"))

  count <- 0
  out <- df |>
    group_by(g) |>
    group_by(
      big = {
        count <<- count + 1
        x > mean(x)
      },
      .add = TRUE
    )
  expect_equal(out$big, c(FALSE, FALSE, TRUE, TRUE))
  expect_equal(count, 1L)
  expect_equal(group_vars(out), c("g", "big"))

  count <- 0
  out <- df |>
    group_by(g) |>
    mutate(big = {
      count <<- count + 1
      x > mean(x)
    }) |>
    group_by(big)
  expect_equal(out$big, c(FALSE, TRUE, FALSE, TRUE))
  expect_equal(count, 2L)
  expect_equal(group_vars(out), c("big"))

  count <- 0
  out <- df |>
    group_by(g) |>
    mutate(big = {
      count <<- count + 1
      x > mean(x)
    }) |>
    group_by(big, .add = TRUE)
  expect_equal(out$big, c(FALSE, TRUE, FALSE, TRUE))
  expect_equal(count, 2L)
  expect_equal(group_vars(out), c("g", "big"))
})

test_that("joins preserve grouping", {
  df <- data.frame(x = rep(1:2, each = 4), y = rep(1:4, each = 2))
  g <- group_by(df, x)

  expect_equal(
    group_vars(inner_join(
      g,
      g,
      by = c("x", "y"),
      relationship = "many-to-many"
    )),
    "x"
  )
  expect_equal(
    group_vars(left_join(
      g,
      g,
      by = c("x", "y"),
      relationship = "many-to-many"
    )),
    "x"
  )
  expect_equal(group_vars(semi_join(g, g, by = c("x", "y"))), "x")
  expect_equal(group_vars(anti_join(g, g, by = c("x", "y"))), "x")
})

test_that("constructors drops groups", {
