test_that("group_by() and ungroup() give meaningful error messages", {
  expect_snapshot({
    df <- tibble(x = 1, y = 2)

    (expect_error(df |> group_by(unknown)))
    (expect_error(df |> ungroup(x)))
    (expect_error(df |> group_by(x, y) |> ungroup(z)))

    (expect_error(df |> group_by(z = a + 1)))
  })
})

# Deprecation -------------------------------------------------------------

test_that("group_by(add =) is defunct", {
  # While it was being deprecated, it was getting passed through the `...`
  # down to `group_by_prepare()`.
  df <- tibble(x = 1, y = 2)

  expect_snapshot(error = TRUE, {
    group_by(df, x, add = TRUE)
  })
})

test_that("group_by_prepare(add =) is defunct", {
  df <- tibble(x = 1, y = 2)

  # We let this say `group_by()` in the error because it is more likely that
  # that is where it came from
  expect_snapshot(error = TRUE, {
    group_by_prepare(df, x, add = TRUE)
  })
})

test_that("group_by(.dots =) is defunct", {
  # While it was being deprecated, it was getting passed through the `...`
  # down to `group_by_prepare()`.
  df <- tibble(x = 1, y = 1)

  expect_snapshot(error = TRUE, {
    group_by(df, .dots = "x")
  })
})

test_that("group_by_prepare(.dots =) is defunct", {
  df <- tibble(x = 1, y = 1)

  # We let this say `group_by()` in the error because it is more likely that
  # that is where it came from
  expect_snapshot(error = TRUE, {
    group_by_prepare(df, .dots = "x")
  })
})


# --- FILE: https://raw.githubusercontent.com/tidyverse/dplyr/main/tests/testthat/test-group-data.R ---
# group_data --------------------------------------------------------------

test_that("group_data(<data.frame>) returns a data frame", {
  df <- data.frame(x = 1:3)
  gd <- group_data(df)

  expect_s3_class(gd, "data.frame", exact = TRUE)
  expect_equal(gd$.rows, list_of(1:3))
})

test_that("group_data(<tbl_df>) returns a tibble", {
  df <- tibble(x = 1:3)
  gd <- group_data(df)

  expect_s3_class(gd, "tbl_df")
  expect_equal(gd, tibble(".rows" := list_of(1:3)))
})

test_that("group_data(<grouped_df>) returns a tibble", {
  df <- tibble(x = c(1, 1, 2))
  gf <- group_by(df, x)
  gd <- group_data(gf)

  expect_s3_class(gd, "tbl_df")
  expect_equal(
    gd,
    tibble(x = c(1, 2), ".rows" := list_of(1:2, 3L)),
    ignore_attr = TRUE
  )
})

test_that("group_data(<rowwise) returns a tibble", {
  df <- tibble(x = 1:3)
  rf <- rowwise(df)
  gd <- group_data(rf)

  expect_s3_class(gd, "tbl_df")
  expect_equal(gd, tibble(".rows" := list_of(1, 2, 3)))
})

# group_rows() and group_keys() -------------------------------------------

test_that("group_rows() and group_keys() partition group_data()", {
  df <- data.frame(x = 1:2, y = 1:2)
  gf <- group_by(df, x, y)
  gd <- group_data(gf)

  expect_equal(group_keys(gf), gd[1:2], ignore_attr = TRUE) # .drop attribute
  expect_equal(group_rows(gf), gd[[3]])
})

test_that("group_keys(...) is defunct", {
  df <- tibble(x = 1, y = 2)

  expect_snapshot(error = TRUE, {
    group_keys(df, x)
  })
})

# group_indices() ---------------------------------------------------------

test_that("no arg group_indices() is deprecated", {
  df <- tibble(x = 1)

  expect_snapshot({
    out <- summarise(df, id = group_indices())
  })

  expect_equal(out, tibble(id = 1))
})

test_that("group_indices(...) is deprecated", {
  df <- tibble(x = 1, y = 2)

  expect_snapshot(error = TRUE, {
    group_indices(df, x)
  })
})

test_that("group_indices() returns expected values", {
  df <- tibble(x = c("b", "a", "b"))
  gf <- group_by(df, x)

  expect_equal(group_indices(df), c(1, 1, 1))
  expect_equal(group_indices(gf), c(2, 1, 2))
})

test_that("group_indices() handles 0 rows data frames (#5541)", {
