# output type ---------------------------------------------------------------

test_that("joins x preserve type of x", {
  df1 <- data.frame(x = 1)
  df2 <- tibble(x = 2)

  expect_s3_class(inner_join(df1, df2, by = "x"), "data.frame", exact = TRUE)
  expect_s3_class(inner_join(df2, df1, by = "x"), "tbl_df")
})

test_that("joins preserve groups", {
  gf1 <- tibble(a = 1:3) |> group_by(a)
  gf2 <- tibble(a = rep(1:4, 2), b = 1) |> group_by(b)

  i <- count_regroups(out <- inner_join(gf1, gf2, by = "a"))
  expect_equal(i, 1L)
  expect_equal(group_vars(out), "a")

  i <- count_regroups(out <- semi_join(gf1, gf2, by = "a"))
  expect_equal(i, 0L)
  expect_equal(group_vars(out), "a")

  # once for x + once for each row for y
  i <- count_regroups(out <- nest_join(gf1, gf2, by = "a"))
  expect_equal(i, 4L)
  expect_equal(group_vars(out), "a")
  expect_equal(group_vars(out$gf2[[1]]), "b")
})

test_that("joins respect zero length groups", {
  df1 <- tibble(f = factor(c(1, 1, 2, 2), levels = 1:3), x = c(1, 2, 1, 4)) |>
    group_by(f)

  df2 <- tibble(f = factor(c(2, 2, 3, 3), levels = 1:3), y = c(1, 2, 3, 4)) |>
    group_by(f)

  expect_equal(
    group_size(left_join(df1, df2, by = "f", relationship = "many-to-many")),
    c(2, 4)
  )
  expect_equal(
    group_size(right_join(df1, df2, by = "f", relationship = "many-to-many")),
    c(4, 2)
  )
  expect_equal(
    group_size(full_join(df1, df2, by = "f", relationship = "many-to-many")),
    c(2, 4, 2)
  )
  expect_equal(group_size(anti_join(df1, df2, by = "f")), c(2))
  expect_equal(
    group_size(inner_join(df1, df2, by = "f", relationship = "many-to-many")),
    c(4)
  )

  df1 <- tibble(f = factor(c(1, 1, 2, 2), levels = 1:3), x = c(1, 2, 1, 4)) |>
    group_by(f, .drop = FALSE)
  df2 <- tibble(f = factor(c(2, 2, 3, 3), levels = 1:3), y = c(1, 2, 3, 4)) |>
    group_by(f, .drop = FALSE)

  expect_equal(
    group_size(left_join(df1, df2, by = "f", relationship = "many-to-many")),
    c(2, 4, 0)
  )
  expect_equal(
    group_size(right_join(df1, df2, by = "f", relationship = "many-to-many")),
    c(0, 4, 2)
  )
  expect_equal(
    group_size(full_join(df1, df2, by = "f", relationship = "many-to-many")),
    c(2, 4, 2)
  )
  expect_equal(group_size(anti_join(df1, df2, by = "f")), c(2, 0, 0))
  expect_equal(
    group_size(inner_join(df1, df2, by = "f", relationship = "many-to-many")),
    c(0, 4, 0)
  )
})

test_that("group column names reflect renamed duplicate columns (#2330)", {
  df1 <- tibble(x = 1:5, y = 1:5) |> group_by(x, y)
  df2 <- tibble(x = 1:5, y = 1:5)

  out <- inner_join(df1, df2, by = "x")
  expect_equal(group_vars(out), "x")
  # TODO: fix this issue: https://github.com/tidyverse/dplyr/issues/4917
  # expect_equal(group_vars(out), c("x", "y.x"))
})

test_that("rowwise group structure is updated after a join (#5227)", {
  df1 <- rowwise(tibble(x = 1:2))
  df2 <- tibble(x = c(1:2, 2L))

  x <- left_join(df1, df2, by = "x")

  expect_identical(group_rows(x), list_of(1L, 2L, 3L))
})

# deprecated ----------------------------------------------------------------

test_that("by = character() generates cross (#4206)", {
  local_options(lifecycle_verbosity = "quiet")

  df1 <- tibble(x = 1:2)
  df2 <- tibble(y = 1:2)
  out <- left_join(df1, df2, by = character())

  expect_equal(out$x, rep(1:2, each = 2))
  expect_equal(out$y, rep(1:2, 2))
})

test_that("`by = character()` technically respects `unmatched`", {
  local_options(lifecycle_verbosity = "quiet")

  df1 <- tibble()
  df2 <- tibble(x = 1)

  expect_snapshot(error = TRUE, {
    left_join(df1, df2, by = character(), unmatched = "error")
  })
})

test_that("`by = character()` technically respects `relationship`", {
  local_options(lifecycle_verbosity = "quiet")

  df <- tibble(x = 1:2)

  expect_snapshot(error = TRUE, {
    left_join(df, df, by = character(), relationship = "many-to-one")
  })
})

test_that("`by = character()` for a cross join is deprecated (#6604)", {
  df1 <- tibble(x = 1:2)
  df2 <- tibble(y = 1:2)

  # Mutating join
  expect_snapshot({
    out <- left_join(df1, df2, by = character())
  })

  # Filtering join
  expect_snapshot({
    out <- semi_join(df1, df2, by = character())
  })

  # Nest join
  expect_snapshot({
    out <- nest_join(df1, df2, by = character())
  })
})

test_that("`by = named character()` for a cross join works", {
  # Used by the sift package
  df1 <- tibble(x = 1:2)
  df2 <- tibble(y = 1:2)

  by <- set_names(character(), nm = character())

  expect_snapshot({
    out <- left_join(df1, df2, by = by)
  })
  expect_identical(
    out,
    cross_join(df1, df2)
  )
})

test_that("`by = list(x = character(), y = character())` for a cross join is deprecated (#6604)", {
  df1 <- tibble(x = 1:2)
  df2 <- tibble(y = 1:2)

  expect_snapshot({
    out <- left_join(df1, df2, by = list(x = character(), y = character()))
  })
})


# --- FILE: https://raw.githubusercontent.com/tidyverse/dplyr/main/tests/testthat/test-lead-lag.R ---
test_that("`lead()` / `lag()` get the direction right", {
  expect_identical(lead(1:5), c(2:5, NA))
  expect_identical(lag(1:5), c(NA, 1:4))
})

test_that("If n = 0, lead and lag return x", {
  x <- c(10L, 8L, 1L, 3L, 6L, 9L, 4L, 2L, 5L, 7L)
  expect_equal(lead(x, 0), x)
  expect_equal(lag(x, 0), x)
})

test_that("If n = length(x), returns all missing", {
  x <- c(10L, 8L, 1L, 3L, 6L, 9L, 4L, 2L, 5L, 7L)

  expect_equal(lead(x, length(x)), rep(NA_integer_, length(x)))
  expect_equal(lag(x, length(x)), rep(NA_integer_, length(x)))
})

test_that("`lag()` gives informative error for <ts> objects", {
  expect_snapshot(error = TRUE, {
    lag(ts(1:10))
  })
})

test_that("lead() and lag() work for matrices (#5028)", {
  m <- matrix(1:6, ncol = 2)
  expect_equal(
    lag(m, 1),
    matrix(c(NA_integer_, 1L, 2L, NA_integer_, 4L, 5L), ncol = 2)
  )
  expect_equal(
    lag(m, 1, default = NA),
    matrix(c(NA_integer_, 1L, 2L, NA_integer_, 4L, 5L), ncol = 2)
  )

  expect_equal(
    lead(m, 1),
    matrix(c(2L, 3L, NA_integer_, 5L, 6L, NA_integer_), ncol = 2)
  )
  expect_equal(
    lead(m, 1, default = NA),
    matrix(c(2L, 3L, NA_integer_, 5L, 6L, NA_integer_), ncol = 2)
  )
})

test_that("lead and lag preserve factors", {
  x <- factor(c("a", "b", "c"))

  expect_equal(levels(lead(x)), c("a", "b", "c"))
  expect_equal(levels(lag(x)), c("a", "b", "c"))
})

test_that("lead and lag preserves dates and times", {
  x <- as.Date("2013-01-01") + 1:3
  y <- as.POSIXct(x)

  expect_s3_class(lead(x), "Date")
  expect_s3_class(lag(x), "Date")

  expect_s3_class(lead(y), "POSIXct")
  expect_s3_class(lag(y), "POSIXct")
})

test_that("`lead()` / `lag()` validate `n`", {
  expect_snapshot(error = TRUE, {
    lead(1:5, n = 1:2)
    lead(1:5, -1)
  })
  expect_snapshot(error = TRUE, {
    lag(1:5, n = 1:2)
    lag(1:5, -1)
  })
})

test_that("`lead()` / `lag()` check for empty dots", {
  expect_snapshot(error = TRUE, {
    lead(1:5, deault = 1)
  })
  expect_snapshot(error = TRUE, {
    lag(1:5, deault = 1)
  })
})

test_that("`lead()` / `lag()` require that `x` is a vector", {
  expect_snapshot(error = TRUE, {
    lead(environment())
  })
  expect_snapshot(error = TRUE, {
    lag(environment())
  })
})

