  expect_equal(df |> select(a = b), tibble(a = 2))

  df <- tibble(a = 1, b = 2, c = 3) |> group_by(a, b)
  expect_snapshot({
    expect_equal(df |> select(a = c), tibble(b = 2, a = 3) |> group_by(b))
